<script setup lang="ts">import{ref}from'vue';import{postJSON}from'../services/api';const rows=ref<any[]>([{route_id:'Candidate A',distance_km:450,traffic_level:7,weather_severity:.4,route_risk:6,delay_probability:.65,shipping_cost_usd:980,supplier_reliability:.9},{route_id:'Candidate B',distance_km:500,traffic_level:3,weather_severity:.15,route_risk:3,delay_probability:.25,shipping_cost_usd:1080,supplier_reliability:.95},{route_id:'Candidate C',distance_km:430,traffic_level:8,weather_severity:.7,route_risk:8,delay_probability:.8,shipping_cost_usd:900,supplier_reliability:.86}]);const ranked=ref<any[]>([]);async function rank(){ranked.value=(await postJSON('/routes/recommend',{candidates:rows.value})).recommendations}</script><template><section class="panel"><h2>Smart Route Ranker</h2><p class="muted">Ranks supplied or dataset-derived candidates. Lower score is preferred; no live conditions are assumed unless explicitly integrated.</p><button @click="rank">Rank Candidates</button><table v-if="ranked.length"><thead><tr><th>Rank</th><th>Route</th><th>Score</th><th>Traffic</th><th>Risk</th><th>Cost</th></tr></thead><tbody><tr v-for="r in ranked"><td>{{r.rank}}</td><td>{{r.route_id}}</td><td>{{r.smart_route_score.toFixed(3)}}</td><td>{{r.traffic_level}}</td><td>{{r.route_risk}}</td><td>${{r.shipping_cost_usd}}</td></tr></tbody></table></section></template>